var SYM="!@#$%^&*()_+-=[]{}|;:,.<>?/`~\"'\\";
function charset(pw){
  var set=0;
  if(/[a-z]/.test(pw)) set++;
  if(/[A-Z]/.test(pw)) set++;
  if(/[0-9]/.test(pw)) set++;
  if(/[^A-Za-z0-9]/.test(pw)) set++;
