}
function poolSize(pw){ var n=0; if(/[a-z]/.test(pw))n+=26; if(/[A-Z]/.test(pw))n+=26; if(/[0-9]/.test(pw))n+=10; if(/[^A-Za-z0-9]/.test(pw))n+=SYM.length; return n; }
function estimate(pw){
  if(!pw) return {length:0,pool:0,entropy:0,rating:'—'};
  var n=poolSize(pw), L=pw.length;
  var bits=Math.round(L*Math.log2(n)*10)/10;
  var rating = bits<28?'极弱':bits<40?'弱':bits<60?'中等':bits<80?'强':'极强';
  return {length:L,pool:n,entropy:bits,rating:rating};
}
